        const auto xf = tmp.getChildFile ("x.json"); xf.replaceWithText (R"J([{"name":"Only VST3","file":"/x/Only.vst3","uid":"ba5f7ab2","version":"1.0.0","vendor":"Acme"}])J");
        const auto before = vst3Extras().size();
