            // WZ-CONTRACT-8b B'S COUNTS (ruling 7): this run sent 8 - 6 accepted, 1 refused (validator), 1 HELD (unknown schema). Received counts
            // all three; accepted leaves the held one out; new = the accepted profiles of plugins answered "need"
            check (c1.received == 8 && c1.accepted == 6 && c1.received == c1.accepted + 1 + 1 && c1.fresh == 2 && c1.checked == 5,
                   "contract WZ-CONTRACT-8b: the counts - received " + juce::String (c1.received) + " (8), accepted " + juce::String (c1.accepted) + " (6: the held one left out), new "
                     + juce::String (c1.fresh) + " (2), checked " + juce::String (c1.checked) + " (5)");

            // 8b. ONCE PER PLUGIN COLLECTION, AND THE TWO SERVING LEVELS (Kathy, 21 Oct): another account with Kathy's collection is refused
            // "already claimed for this setup"; its results still count but cannot certify (not independent); the same account with a
            // DIFFERENT collection earns its code and certifies the one it agrees with; a disagreement stays unverified; our own
            // verification certifies too
            scenario ("10_same_collection_other_account");
            const juce::String runX = "run_" + juce::String::toHexString (0x00000000aaaa0001LL).paddedLeft ('0', 16), runY = "run_" + juce::String::toHexString (0x00000000bbbb0002LL).paddedLeft ('0', 16);
            MemoryTokenStore store2; Session s2 (ep, tx, store2, [&] (const juce::String& l) { logLines.add (l); });
            auto dev2 = s2.startDevice(); secrets.push_back (dev2.deviceCode); hook ("/__mock/approve", "{\"account_id\": \"acct_mock_b\"}");
            juce::String w2; const auto p2 = s2.pollOnce (dev2, w2); if (const auto t2 = store2.load()) { secrets.push_back (t2->access); secrets.push_back (t2->refresh); }
            const auto cc2 = catalogueCheck (s2, reqV, runX), ccK = catalogueCheck (s, reqV, "run_" + juce::String::toHexString (0x1234abcd5678ef91LL));   // 27 Oct (B): Kathy's first run is finished - her next check is a new run
            auto statusOf = [] (const CatalogueResult& c, const char* pid) { return c.answers.getProperty ("by_plugin_id", {}).getProperty (juce::Identifier (pid), {}); };
            const auto vOther = statusOf (cc2, "AudioUnit|aaaa0002|1.0"), vKathy = statusOf (ccK, "AudioUnit|aaaa0002|1.0");
            const auto bundle2 = work.getChildFile ("bundle2"); bundle2.getChildFile ("profiles").createDirectory();
            auto profile2 = [&] (const juce::String& id, double g) { const auto rel = "profiles/AudioUnit_" + id + "_1.0.comp_profile.json";
                bundle2.getChildFile (rel).replaceWithText (realProfile (id, "ej_comp_profile/1", g - 1.0)); return rel; };
            auto sendRun = [&] (const juce::String& rid, const juce::StringArray& collection, const juce::String& profilesJson, const juce::String& boxName, const juce::StringArray& needs)
            {
                ensureRun (s2, RunInfo { rid, "2026-10-21T19:00:02Z", 1, collection });
                Outbox b2 { work.getChildFile (boxName) };
                std::map<juce::String, ejmap::wizresults::Identity> ids; for (const auto& n : needs) ids[n] = { "V", "Plug " + juce::StringArray::fromTokens (n, "|", "")[1] };
                ejmap::wizresults::emit (spanned (ejmap::wizresults::fromPack (withToneChecks (juce::JSON::parse ("{\"profiles\": [" + profilesJson + "]}"), bundle2), bundle2, rid, true, ids, {}, {}, needs)), b2, {});
                drain (s2, b2, RunInfo { rid, "2026-10-21T19:00:02Z", 1, collection });
                juce::Array<juce::var> q, o; juce::StringArray sids;
                for (const auto& f : b2.sent().findChildFiles (juce::File::findFiles, false, "*.json.gz")) sids.add (Outbox::resultIdOf (f));
                return complete (s2, rid, "finished", juce::var (q), juce::var (o), sids);
            };
            auto prof = [&] (const char* id, double g) { return "{\"product\": \"Plug " + juce::String (id) + "\", \"kind\": \"compressor\", \"plugin_id\": \"AudioUnit|" + juce::String (id) + "|1.0\", \"profile\": \"" + profile2 (id, g) + "\"}"; };
            const auto cX = sendRun (runX, kathyCollection, prof ("aaaa0002", 1.2), "box_x", needOf (cc2));                     // the SAME setup as Kathy's
            const auto levelAfterX = mockState().getProperty ("served", {}).getProperty ("AudioUnit|aaaa0002|1.0", {});
            const auto reqY = juce::JSON::parse ("{\"plugins\": [{\"plugin_id\": \"AudioUnit|bbbb0001|1.0\", \"vendor\": \"V\"}, {\"plugin_id\": \"AudioUnit|bbbb0002|1.0\", \"vendor\": \"V\"}, {\"plugin_id\": \"AudioUnit|aaaa0002|1.0\", \"vendor\": \"V\"}]}");
            scenario ("11_second_tester_certifies");
            const auto ccY = catalogueCheck (s2, reqY, runY);   // 21 Oct (Sean): the minimum counts plugins CHECKED under this run - this account checks run Y's
            const auto cY = sendRun (runY, juce::StringArray { "AudioUnit|bbbb0001|1.0", "AudioUnit|bbbb0002|1.0", "AudioUnit|aaaa0002|1.0" },
                                     prof ("aaaa0002", 1.3) + "," + prof ("aaaa0004", 4.0), "box_y", needOf (ccY));           // another setup: agrees on 0002 (0.3), not on 0004 (3.0)
            const auto served = mockState().getProperty ("served", {});
            const auto l2 = served.getProperty ("AudioUnit|aaaa0002|1.0", {}), l4 = served.getProperty ("AudioUnit|aaaa0004|1.0", {});
            const auto cc3 = catalogueCheck (s2, reqV, "run_" + juce::String::toHexString (0x00000000bbbb0003LL).paddedLeft ('0', 16));   // 27 Oct (B): runY is finished - a new run checks
            hook ("/__mock/verify", "{\"plugin_id\": \"AudioUnit|aaaa0004|1.0\"}");
            const auto l4v = mockState().getProperty ("served", {}).getProperty ("AudioUnit|aaaa0004|1.0", {});
            const auto withApple = juce::JSON::parse ("{\"plugins\": [{\"plugin_id\": \"AudioUnit|1|1\", \"vendor\": \"Apple\"}, {\"plugin_id\": \"AudioUnit|2|1\", \"vendor\": \"V\"}, {\"plugin_id\": \"AudioUnit|2|1\", \"vendor\": \"V\"}]}");
            check (p2 == Poll::ok && kathyCollection.size() == 5 && collectionFromRequest (withApple) == juce::StringArray { "AudioUnit|2|1" }
                   && vOther.getProperty ("status", "") == juce::var ("need") && vOther.getProperty ("reason", "") == juce::var ("verify")
                   && vKathy.getProperty ("status", "") == juce::var ("have") && vKathy.getProperty ("level", "") == juce::var ("mapped_unverified")
                   && ejmap::wizroute::fromCatalogue (cc2.answers, "AudioUnit|aaaa0002|1.0").rule == ejmap::wizroute::Rule::C
                   && ejmap::wizroute::fromCatalogue (cc2.answers, "AudioUnit|aaaa0002|1.0").why.contains ("verify")
                   && cX.done && ! cX.eligible && cX.code.isEmpty() && cX.reason == "collection_already_claimed" && cX.message == "The free month has already been claimed for this setup."
                   && levelAfterX.getProperty ("level", "") == juce::var ("mapped_unverified") && (int) levelAfterX.getProperty ("not_independent", 0) == 1
                   && cY.done && cY.eligible && cY.code.startsWith ("EJ-FREE-") && cY.code != c1.code
                   && l2.getProperty ("level", "") == juce::var ("certified") && l2.getProperty ("certified_by", "") == juce::var ("second_tester")
                   && l4.getProperty ("level", "") == juce::var ("mapped_unverified") && (int) l4.getProperty ("disagreed", 0) == 1
                   && statusOf (cc3, "AudioUnit|aaaa0002|1.0").getProperty ("level", "") == juce::var ("certified")
                   && l4v.getProperty ("level", "") == juce::var ("certified") && l4v.getProperty ("certified_by", "") == juce::var ("echojay_verification"),
                   "contract WZ-CONTRACT-13: once per plugin collection - another account on Kathy's setup: '" + cX.message + "' (" + cX.reason + "); its result cannot certify; another setup earns '"
                   + cY.code + "' and certifies the result it agrees with; a disagreement stays unverified; our own verification certifies");
            // 8c. THE MINIMUM COUNTS PLUGINS CHECKED, NOT NEW UPLOADS (Sean, 21 Oct; contract v1 §5), from the server's own records: a third
            // account's finished run with nothing uploaded - 1 of its 3 collection plugins checked -> "this run checked 1"; once it has checked
            // 2 (the minimum here) the same run earns a code with 0 uploads. A fourth account whose upload failed the cheat checks gets none
            auto signInAs = [&] (MemoryTokenStore& st, const juce::String& acct) -> Session&
            { auto* ss = new Session (ep, tx, st, [&] (const juce::String& l) { logLines.add (l); }); auto d = ss->startDevice(); secrets.push_back (d.deviceCode);
              hook ("/__mock/approve", "{\"account_id\": \"" + acct + "\"}"); juce::String ww; ss->pollOnce (d, ww); if (const auto t = st.load()) { secrets.push_back (t->access); secrets.push_back (t->refresh); } return *ss; };
            scenario ("12_below_minimum_then_met_by_checks");
            const juce::String runZ = "run_" + juce::String::toHexString (0x00000000cccc0003LL).paddedLeft ('0', 16), runW = "run_" + juce::String::toHexString (0x00000000dddd0004LL).paddedLeft ('0', 16);
            MemoryTokenStore store3, store4; std::unique_ptr<Session> s3 (&signInAs (store3, "acct_mock_c")), s4 (&signInAs (store4, "acct_mock_d"));
            auto req1 = [] (std::initializer_list<const char*> ids) { juce::String j = "{\"plugins\": ["; bool first = true; for (const char* i : ids) { j << (first ? "" : ",") << "{\"plugin_id\": \"AudioUnit|" << i << "|1.0\", \"vendor\": \"V\"}"; first = false; } return juce::JSON::parse (j + "]}"); };
            const juce::StringArray colZ { "AudioUnit|cccc0001|1.0", "AudioUnit|cccc0002|1.0", "AudioUnit|cccc0003|1.0" };
            const auto ccZ1 = catalogueCheck (*s3, req1 ({ "cccc0001" }), runZ);
            catalogueCheck (*s3, req1 ({ "cccc0002" }), "run_" + juce::String::toHexString (0x00000000eeee0005LL).paddedLeft ('0', 16));   // under ANOTHER run: does not count for runZ
            ensureRun (*s3, RunInfo { runZ, "2026-10-21T19:00:02Z", 0, colZ });
            const juce::var noQ (juce::Array<juce::var> {});
            Outbox boxZ { work.getChildFile ("outbox_z") }; const RunInfo riZ { runZ, "2026-10-21T19:00:02Z", 0, colZ };
            coverNeeds (*s3, boxZ, riZ, needOf (ccZ1));   // v1.1: an outcome for every "need" - not a measurement
            auto sentOf = [] (const Outbox& b) { juce::StringArray ids; for (const auto& f : b.sent().findChildFiles (juce::File::findFiles, false, "*.json.gz")) ids.add (Outbox::resultIdOf (f)); return ids; };
            const auto z1 = complete (*s3, runZ, "finished", noQ, noQ, sentOf (boxZ));
            const auto zDone = catalogueCheck (*s3, req1 ({ "cccc0002" }), runZ);   // 27 Oct (B): a finished run is never checked again
            const juce::String runZ2 = "run_" + juce::String::toHexString (0x00000000cccc0013LL).paddedLeft ('0', 16);
            const auto ccZ2 = catalogueCheck (*s3, req1 ({ "cccc0001", "cccc0002" }), runZ2);   // a NEW run: two checked
            ensureRun (*s3, RunInfo { runZ2, "2026-10-21T19:00:02Z", 0, colZ });
            Outbox boxZ2 { work.getChildFile ("outbox_z2") }; coverNeeds (*s3, boxZ2, RunInfo { runZ2, "2026-10-21T19:00:02Z", 0, colZ }, needOf (ccZ2));
            const auto z2 = complete (*s3, runZ2, "finished", noQ, noQ, sentOf (boxZ2));
            scenario ("13_failed_cheat_check");
            const auto ccW = catalogueCheck (*s4, req1 ({ "dddd0001", "dddd0002", "dddd0003" }), runW);
            const juce::StringArray colW { "AudioUnit|dddd0001|1.0", "AudioUnit|dddd0002|1.0", "AudioUnit|dddd0003|1.0" };
            ensureRun (*s4, RunInfo { runW, "2026-10-21T19:00:02Z", 0, colW });
            {   // a result whose SHA-256 does not match its body: a tampered upload (the cheat checks)
                const auto body = juce::String ("{\"schema\": \"ej_wizard_result/1\"}"); const auto gz = gzip (body);
                s4->call ("PUT", "runs/" + runW + "/results/" + resultIdFor (runW, "outcome", "AudioUnit|dddd0001|1.0"), {}, &gz, juce::String::repeatedString ("0", 64));
            }
            // 27 Oct (B): a completed run takes nothing more (409 run_completed) - the early /complete has its OWN run, with its own tampered upload
            const juce::String runW0 = "run_" + juce::String::toHexString (0x00000000dddd0014LL).paddedLeft ('0', 16);
